FILE: app/src/focus.ts
```ts
import type { ArcRotateCamera } from "@babylonjs/lite";
import { getCameraPosition, getViewMatrix } from "@babylonjs/lite";

export function focusOn(camera: ArcRotateCamera, point: { x: number; y: number; z: number }): void {
  const target = camera.target;
  target.x = point.x;
  target.y = point.y;
  target.z = point.z;
  camera.target = target;

  // Touch the lazy position/view caches so same-frame reads see the new centre.
  void getCameraPosition(camera);
  void getViewMatrix(camera);
}
```

I moved the arc-rotate orbit centre by mutating and reassigning `camera.target`, then touched the public position/view readers to make same-frame label reads reflect it. I wasn’t sure whether the package root exports those readers or whether target mutation alone already invalidates the view cache, but the target change is the essential part.
